[CmdletBinding(SupportsShouldProcess)] param([string]$Distro='Ubuntu-26.04',[int]$Port=2222)
$ErrorActionPreference='Stop'; $admin=([Security.Principal.WindowsPrincipal][Security.Principal.WindowsIdentity]::GetCurrent()).IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator); if(!$admin){throw 'Run from an elevated PowerShell'}
$tailscale=Get-NetIPAddress -AddressFamily IPv4 -ErrorAction SilentlyContinue|Where-Object InterfaceAlias -Match Tailscale|Select-Object -First 1; if(!$tailscale){throw 'Tailscale interface is not active on Windows'}
$name='VSSS WSL SSH via Tailscale'; if($PSCmdlet.ShouldProcess($name,"allow TCP $Port on Tailscale interface")){if(!(Get-NetFirewallRule -DisplayName $name -ErrorAction SilentlyContinue)){New-NetFirewallRule -DisplayName $name -Direction Inbound -Action Allow -Protocol TCP -LocalPort $Port -InterfaceAlias $tailscale.InterfaceAlias -Profile Any|Out-Null}}
$wslCreatorId='{40E0AC32-46A5-438A-A0B2-2B479E8F2E90}'; $hyperVRule='VSSS-WSL-SSH-2222'
if(Get-Command New-NetFirewallHyperVRule -ErrorAction SilentlyContinue){if($PSCmdlet.ShouldProcess($hyperVRule,"allow WSL TCP $Port from Tailscale CGNAT")){if(!(Get-NetFirewallHyperVRule -Name $hyperVRule -ErrorAction SilentlyContinue)){New-NetFirewallHyperVRule -Name $hyperVRule -DisplayName 'VSSS WSL SSH via Tailscale' -Direction Inbound -VMCreatorId $wslCreatorId -Protocol TCP -LocalPorts $Port -RemoteAddresses '100.64.0.0/10'|Out-Null}}}
$action=New-ScheduledTaskAction -Execute 'wsl.exe' -Argument "-d $Distro --exec /bin/sh -lc 'exec sleep infinity'"; $trigger=New-ScheduledTaskTrigger -AtLogOn; if($PSCmdlet.ShouldProcess('VSSS-WSL-Start','register explicit keepalive task')){Register-ScheduledTask -TaskName 'VSSS-WSL-Start' -Action $action -Trigger $trigger -Description 'Starts target WSL distro for SSH; disable to stop keepalive.' -Force|Out-Null}